function makeEnemy(){if(isSafe()){enemy=null;enemiesLeft=0;combatState='safe';return}enemiesLeft=isBoss()?1:Math.min(4,1+Math.floor((s.floor-1)/5));spawnEnemy();combatState='fight'}

