let activeNpc='mira';const npcData={mira:{name:'Mira',role:'Cartographer',greeting:'The stairs do not lead upward so much as inward. Tell me what you seek, traveler.',stories:['I once mapped a corridor that only appeared in the reflection of a rain puddle. At its end, a homesick star had fallen asleep. I showed it the way back by drawing the night sky from memory.','A tiny fox followed my expedition for seven floors, carrying a brass compass in its teeth. At the summit it left the compass beside a door—and the needle pointed home.']},oren:{name:'Oren',role:'Smith',greeting:'Rest your hands, adventurer. Even steel needs a quiet moment between battles.',stories:['My mentor forged a bell from the first gate we ever opened. It never rang for danger—only for someone who had found a reason to keep going.','A cracked sword came to my anvil with a note: “It belonged to the one who spared me.” I mended the blade, but left the crack. Some marks are promises.']},sable:{name:'Sable',role:'Storykeeper',greeting:'Every floor keeps a secret. Which one would you like to hear?',stories:['Long ago, the tower asked a moth why it climbed toward the moon. “I am not climbing to reach it,” said the moth. “I am climbing so the dark has a little company.”','A king locked his greatest treasure behind a door with no keyhole. Years later, a child knocked. The door opened—not because the child was strong, but because someone was finally there to listen.']}};let npcStories=0;
 function appendChat(who,text){let p=document.createElement('p');p.className=who==='you'?'chat-you':'chat-npc';p.textContent=(who==='you'?'YOU: ':`${npcData[activeNpc].name.toUpperCase()}: `)+text;$('chatLog').append(p);while($('chatLog').children.length>10)$('chatLog').firstElementChild.remove();$('chatLog').scrollTop=$('chatLog').scrollHeight}
 function npcReply(message){let q=message.toLowerCase(),npc=npcData[activeNpc],theme=pickTheme()[0];if(/story|tale|legend|once|tell me/.test(q)){let tale=npc.stories[npcStories++%npc.stories.length];return `${tale} Here, on Floor ${s.floor}, even ${theme.toLowerCase()} has a story waiting for you.`}if(/advice|help|tip|how/.test(q))return activeNpc==='mira'?'Watch the rhythm of each guardian. A glowing wind-up is your invitation to evade. The next waystation waits five floors from the last.':activeNpc==='oren'?'Spend your points where your fighting style needs them. Vitality helps you endure; power ends a fight sooner. Save ore for armor when you can.':'Ask a keeper for a story when the climb feels too quiet. And never ignore a safe floor—it is a gift, not a detour.';if(/floor|tower|spire|where/.test(q))return `This is Floor ${s.floor}, within ${theme}. The tower remembers every step, though it never tells the same story twice.`}if(/name|who are/.test(q))return `I am ${npc.name}, the ${npc.role.toLowerCase()}. I keep this waystation for everyone still climbing.`;return `I hear you. The tower can make a person feel small, but you have climbed all the way to Floor ${s.floor}. Would you like me to tell you a story?`}
 function sendChat(message){if(!isSafe()||!message.trim())return;appendChat('you',message.trim());appendChat('npc',npcReply(message.trim()))}
